import { Component, OnDestroy, computed, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  REPORT_FILES,
  reportFailureMessage,
  reportRangeError,
  centralIsoDate,
  type ReportKind,
} from '../../live-reports';
import { centralDayTime, centralTime } from '../../shared/app-time';

/** CSV reports by instrument, client segment, trading activity and buy/sell balance, generated by the insights service (TS-18.6). */
@Component({
  selector: 'app-reports-page',
  imports: [FormsModule],
  templateUrl: './reports-page.html',
  styleUrl: './reports-page.scss',
})
export class ReportsPage implements OnDestroy {
  readonly reportFiles = inject(REPORT_FILES, { optional: true });
  /** Reports generated server-side from the insights trade dataset (BR-16). */
  readonly reportCatalog: readonly {
    kind: ReportKind;
    name: string;
    description: string;
  }[] = [
    {
      kind: 'instrument-report',
      name: 'Instrument Report',
      description: 'Trade count, quantity, notional and average execution price for each instrument.',
    },
    {
      kind: 'client-segment-report',
      name: 'Client Segment Report',
      description: 'Trades, unique clients, quantity and notional by client segment.',
    },
    {
      kind: 'trading-activity-report',
      name: 'Trading Activity Report',
      description: 'Executed trades, active clients, quantity and notional per day and hour.',
    },
    {
      kind: 'buy-sell-balance-report',
      name: 'Buy/Sell Balance Report',
      description: 'Buy and sell trades, quantities and notional by instrument, with net values.',
    },
  ];
  readonly today = centralIsoDate();
  /** Reports always carry a date range; it starts as the last 30 Central days, ending today. */
  readonly reportStart = signal(centralIsoDate(new Date(), 29));
  readonly reportEnd = signal(this.today);
  readonly reportDateError = computed(() => reportRangeError(this.reportStart(), this.reportEnd()));
  /** Quick ranges that fill in both dates, each ending today (New York). */
  readonly presets = [
    { label: '7D', days: 7 },
    { label: '30D', days: 30 },
    { label: '90D', days: 90 },
    { label: '1Y', days: 366 },
  ];
  /** How many days the chosen range covers, both dates included. */
  readonly rangeDays = computed(() => {
    const start = Date.parse(this.reportStart() + 'T00:00:00Z');
    const end = Date.parse(this.reportEnd() + 'T00:00:00Z');
    return Number.isNaN(start) || Number.isNaN(end) ? 0 : Math.round((end - start) / 86_400_000) + 1;
  });
  /** "Reporting period: 30 days, 2026-09-27 to 2026-10-26." for the status region; the error is announced instead when the dates are invalid. */
  readonly periodAnnouncement = computed(() => this.reportDateError()
    ? ''
    : `Reporting period: ${this.rangeDays()} ${this.rangeDays() === 1 ? 'day' : 'days'}, ${this.reportStart()} to ${this.reportEnd()}.`);
  readonly generating = signal<ReportKind | null>(null);
  readonly dayTime = centralDayTime;
  readonly notice = signal('');
  readonly exports = signal<
    { name: string; at: Date; rows: number; csv: string; filename?: string; period?: string }[]
  >([]);
  private destroyed = false;

  async generateReport(report: { kind: ReportKind; name: string }): Promise<void> {
    const dateError = this.reportDateError();
    if (dateError) {
      this.notice.set(dateError);
      return;
    }
    if (!this.reportFiles) {
      this.notice.set('Report generation is unavailable.');
      return;
    }
    if (this.generating()) {
      return;
    }
    const range = { startDate: this.reportStart(), endDate: this.reportEnd() };
    this.generating.set(report.kind);
    this.notice.set('');
    try {
      const file = await this.reportFiles.generate(report.kind, range);
      if (this.destroyed) {
        return;
      }
      const rows = Math.max(file.csv.split(/\r?\n/).filter((line) => line.trim()).length - 1, 0);
      const generated = {
        name: report.name,
        at: new Date(),
        rows,
        csv: file.csv,
        filename: file.filename,
        period: `${range.startDate} – ${range.endDate}`,
      };
      this.exports.update((list) => [generated, ...list]);
      this.download(generated);
      // The notice is an <output> (a polite status), so the row count is read out as well as shown.
      this.notice.set(
        rows
          ? `${report.name} generated for ${generated.period}: ${rows} ${rows === 1 ? 'row' : 'rows'}.`
          : `${report.name} generated, but no trades were executed between ${generated.period}.`,
      );
    } catch (error) {
      if (!this.destroyed) {
        this.notice.set(reportFailureMessage(error));
      }
    } finally {
      this.generating.set(null);
    }
  }

  /** When this report was last exported this session, e.g. "Exported 2:53 PM CT"; empty before that. */
  lastExport(name: string): string {
    const latest = this.exports().find((entry) => entry.name === name);
    return latest ? `Exported ${centralTime(latest.at)}` : '';
  }

  /** Sets the range to the last `days` New York days, ending today. */
  usePreset(days: number): void {
    this.reportStart.set(centralIsoDate(new Date(), days - 1));
    this.reportEnd.set(this.today);
  }
  isPreset(days: number): boolean {
    return this.reportEnd() === this.today && this.reportStart() === centralIsoDate(new Date(), days - 1);
  }

  download(report: { name: string; csv: string; filename?: string }) {
    const url = URL.createObjectURL(
      new Blob(['﻿' + report.csv], { type: 'text/csv;charset=utf-8' }),
    );
    const a = document.createElement('a');
    a.href = url;
    a.download = report.filename ?? report.name.toLowerCase().replaceAll(' ', '-') + '.csv';
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  ngOnDestroy(): void {
    this.destroyed = true;
  }
}
